-- Behavioural checks for Phase: Inbound integrations: endpoints are Admin+ only (workspace admins get no
-- bypass), tokens and signing secrets are generated by the database, shown once, and never readable;
-- a wrong, disabled, deleted, or rotated token creates nothing and gets the same generic 401; bad,
-- stale, and replayed signatures fail; an Idempotency-Key makes one task; payload mapping (section,
-- assignee, tags, fields by name) with warnings; rate limiting; the creator's access is re-checked;
-- the inbound_received rule trigger and source_is "inbound"; import / copy muting kept; and anon can
-- execute only get_public_form, submit_form, and receive_inbound_webhook.
-- Fresh people for this suite (no memberships from earlier suites):
--   f6f6…01 ib-owner@example.com     owner of IB P
--   f6f6…02 ib-admin@example.com     Admin of P (creates the endpoints)
--   f6f6…03 ib-editor@example.com    Editor of P
--   f6f6…04 ib-viewer@example.com    Viewer of P
--   f6f6…05 ib-outsider@example.com  no memberships
-- plus the workspace admin an earlier suite left (not a member of P).

\set ON_ERROR_STOP 1

create temporary table ib_ids (name text primary key, id uuid) on commit preserve rows;
create temporary table ib_vals (name text primary key, val text) on commit preserve rows;
grant all on ib_ids, ib_vals to authenticated, anon, service_role;

insert into public.allowed_emails (email, note) values
  ('ib-owner@example.com', 'inbound integrations suite'),
  ('ib-admin@example.com', 'inbound integrations suite'),
  ('ib-editor@example.com', 'inbound integrations suite'),
  ('ib-viewer@example.com', 'inbound integrations suite'),
  ('ib-outsider@example.com', 'inbound integrations suite');
insert into auth.users (id, email, email_confirmed_at, raw_user_meta_data) values
  ('f6f6f6f6-0000-4000-8000-000000000001', 'ib-owner@example.com', now(), '{"full_name":"Ola Owner"}'),
  ('f6f6f6f6-0000-4000-8000-000000000002', 'ib-admin@example.com', now(), '{"full_name":"Ada Admin"}'),
  ('f6f6f6f6-0000-4000-8000-000000000003', 'ib-editor@example.com', now(), '{"full_name":"Ed Editor"}'),
  ('f6f6f6f6-0000-4000-8000-000000000004', 'ib-viewer@example.com', now(), '{"full_name":"Vi Viewer"}'),
  ('f6f6f6f6-0000-4000-8000-000000000005', 'ib-outsider@example.com', now(), '{"full_name":"Oz Outsider"}');

insert into ib_ids values
  ('owner', 'f6f6f6f6-0000-4000-8000-000000000001'),
  ('admin', 'f6f6f6f6-0000-4000-8000-000000000002'),
  ('editor', 'f6f6f6f6-0000-4000-8000-000000000003'),
  ('viewer', 'f6f6f6f6-0000-4000-8000-000000000004'),
  ('outsider', 'f6f6f6f6-0000-4000-8000-000000000005'),
  ('ws_admin', (select profile_id from public.workspace_admins where deleted_at is null order by created_at limit 1));

-- Helpers (internal) -------------------------------------------------------------------------------

do $$
begin
  assert (select id from ib_ids where name = 'ws_admin') is not null, 'an earlier suite left a workspace admin';
  assert encode(public.inbound_hmac_sha256(convert_to('Jefe', 'UTF8'), convert_to('what do ya want for nothing?', 'UTF8')), 'hex')
    = '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843', 'HMAC-SHA256 matches RFC 4231 test case 2';
  assert encode(public.inbound_hmac_sha256(convert_to(repeat('k', 100), 'UTF8'), convert_to('1700000000.{"a":"é"}', 'UTF8')), 'hex')
    = '640f1a37564a532fb2e28fdacc3533560344ad9cacb77bb37252f0a275322b04', 'long keys are hashed first (matches Node)';
  assert public.inbound_random_hex() ~ '^[0-9a-f]{64}$' and public.inbound_random_hex() <> public.inbound_random_hex(),
    'random hex is 64 characters and differs each time';
end $$;

-- Fixtures ----------------------------------------------------------------------------------------

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000001', false) is not null as ok \gset

do $$
declare
  ws uuid := '00000000-0000-4000-8000-000000000001';
  p uuid;
  other uuid;
  inbox uuid;
  doing uuid;
  other_section uuid;
  urgent uuid;
  web uuid;
  old_tag uuid;
begin
  insert into public.projects (workspace_id, name) values (ws, 'IB P') returning id into p;
  insert into public.sections (project_id, name, sort_order) values (p, 'Inbox', 1024) returning id into inbox;
  insert into public.sections (project_id, name, sort_order) values (p, 'Doing', 2048) returning id into doing;
  insert into public.projects (workspace_id, name) values (ws, 'IB Other') returning id into other;
  insert into public.sections (project_id, name, sort_order) values (other, 'Elsewhere', 1024) returning id into other_section;
  perform public.add_project_member(p, 'ib-admin@example.com', 'admin');
  perform public.add_project_member(p, 'ib-editor@example.com', 'editor');
  perform public.add_project_member(p, 'ib-viewer@example.com', 'viewer');
  insert into public.custom_fields (project_id, name, field_type, options) values
    (p, 'Priority', 'single_select', '[{"id": "hi", "name": "High", "color": "red"}, {"id": "lo", "name": "Low", "color": "zinc"}]'),
    (p, 'Budget', 'number', '[]'),
    (p, 'Launch', 'date', '[]'),
    (p, 'Reviewers', 'people', '[]');
  insert into public.tags (workspace_id, name) values (ws, 'IB Urgent') returning id into urgent;
  insert into public.tags (workspace_id, name) values (ws, 'IB Web') returning id into web;
