-- Endpoint admin is Admin+ only ---------------------------------------------------------------------

do $$
declare
  p uuid := (select id from ib_ids where name = 'p');
  who text;
begin
  foreach who in array array['editor', 'viewer', 'outsider', 'ws_admin'] loop
    perform set_config('request.jwt.claim.sub', (select id::text from ib_ids where name = who), true);
    begin
      perform public.create_inbound_endpoint(p, 'Nope');
      raise exception '% should not create an endpoint', who;
    exception when insufficient_privilege then null;
    end;
    begin
      insert into public.inbound_endpoints (project_id, name) values (p, 'Direct');
      raise exception '% should not insert an endpoint directly', who;
    exception when insufficient_privilege then null;
    end;
  end loop;
end $$;

select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset

do $$
declare
  p uuid := (select id from ib_ids where name = 'p');
  created jsonb;
begin
  begin
    perform public.create_inbound_endpoint(p, 'Bad section', (select id from ib_ids where name = 'other_section'));
    raise exception 'a section of another project should fail';
  exception when check_violation then null;
  end;
  begin
    perform public.create_inbound_endpoint(p, 'Bad assignee', null, (select id from ib_ids where name = 'outsider'));
    raise exception 'a non-member default assignee should fail';
  exception when check_violation then null;
  end;
  begin
    perform public.create_inbound_endpoint(p, 'Archived tag', null, null, array[(select id from ib_ids where name = 'old_tag')]);
    raise exception 'archived default tags should fail';
  exception when check_violation then null;
  end;
  begin
    perform public.create_inbound_endpoint(p, '   ');
    raise exception 'a blank name should fail';
  exception when check_violation then null;
  end;

  created := public.create_inbound_endpoint(p, ' Website intake ', (select id from ib_ids where name = 'inbox'),
    (select id from ib_ids where name = 'editor'), array[(select id from ib_ids where name = 'urgent')]);
  assert created ->> 'token' ~ '^alhc_in_[0-9a-f]{64}$', format('the token is returned once, got %s', created);
  assert created ->> 'signing_secret' is null, 'no signing secret unless asked';
  insert into ib_ids values ('e1', (created ->> 'id')::uuid);
  insert into ib_vals values ('t1', created ->> 'token');

  created := public.create_inbound_endpoint(p, 'Signed', null, null, '{}', true);
  assert created ->> 'signing_secret' ~ '^whsec_[0-9a-f]{64}$', format('the signing secret is returned once, got %s', created);
  insert into ib_ids values ('e2', (created ->> 'id')::uuid);
  insert into ib_vals values ('t2', created ->> 'token'), ('s2', created ->> 'signing_secret');

  created := public.create_inbound_endpoint(p, 'Throttled');
  insert into ib_ids values ('e3', (created ->> 'id')::uuid);
  insert into ib_vals values ('t3', created ->> 'token');

  created := public.create_inbound_endpoint(p, 'Soon deleted');
  insert into ib_ids values ('e4', (created ->> 'id')::uuid);
  insert into ib_vals values ('t4', created ->> 'token');

  assert (select name from public.inbound_endpoints where id = (select id from ib_ids where name = 'e1')) = 'Website intake',
    'names are trimmed';
  assert (select token_hint from public.inbound_endpoints where id = (select id from ib_ids where name = 'e1'))
    = '…' || right((select val from ib_vals where name = 't1'), 4), 'the hint is the last 4 characters';
  assert (select created_by from public.inbound_endpoints where id = (select id from ib_ids where name = 'e1'))
    = (select id from ib_ids where name = 'admin'), 'the creator is the caller';

  begin
    perform token_hash from public.inbound_endpoints limit 1;
    raise exception 'admins should not read token hashes';
  exception when insufficient_privilege then null;
  end;
  begin
    perform signing_secret from public.inbound_endpoints limit 1;
    raise exception 'admins should not read signing secrets';
  exception when insufficient_privilege then null;
  end;
  begin
    update public.inbound_endpoints set token_hash = repeat('0', 64) where id = (select id from ib_ids where name = 'e1');
    raise exception 'admins should not write token hashes';
  exception when insufficient_privilege then null;
  end;
  begin
    update public.inbound_endpoints set signing_secret = 'whsec_chosen_by_a_person_000000' where id = (select id from ib_ids where name = 'e2');
    raise exception 'admins should not write signing secrets';
  exception when insufficient_privilege then null;
  end;
  begin
    update public.inbound_endpoints set project_id = (select id from ib_ids where name = 'other')
    where id = (select id from ib_ids where name = 'e1');
    raise exception 'endpoints should not move';
  exception when insufficient_privilege then null;
  end;
end $$;

-- Nobody below Admin (and no workspace admin) reads, rotates, or changes endpoints or the log ----------

do $$
declare
  who text;
  hits integer;
begin
  foreach who in array array['editor', 'viewer', 'outsider', 'ws_admin'] loop
    perform set_config('request.jwt.claim.sub', (select id::text from ib_ids where name = who), true);
    assert (select count(*) from public.inbound_endpoints) = 0, format('%s reads no endpoints', who);
    assert (select count(*) from public.inbound_calls) = 0, format('%s reads no calls', who);
    begin
      perform public.rotate_inbound_token((select id from ib_ids where name = 'e1'));
      raise exception '% should not rotate', who;
    exception when no_data_found then null;
    end;
    begin
      perform public.set_inbound_signing_secret((select id from ib_ids where name = 'e1'), true);
      raise exception '% should not set a signing secret', who;
    exception when no_data_found then null;
    end;
    update public.inbound_endpoints set enabled = false where id = (select id from ib_ids where name = 'e1');
    get diagnostics hits = row_count;
    assert hits = 0, format('%s changes no endpoint', who);
  end loop;
end $$;

-- Receiving as anon -----------------------------------------------------------------------------------

reset role;
set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset

do $$
declare
  unknown jsonb;
  r jsonb;
begin
  unknown := public.receive_inbound_webhook('alhc_in_' || repeat('ab', 32), '{"title": "Guess"}');
  assert unknown = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, format('unknown token → generic 401, got %s', unknown);
  r := public.receive_inbound_webhook('not-a-token', '{"title": "Guess"}');
  assert r = unknown, 'malformed token → the same 401';
  r := public.receive_inbound_webhook(null, '{"title": "Guess"}');
  assert r = unknown, 'missing token → the same 401';
  r := public.receive_inbound_webhook(upper((select val from ib_vals where name = 't1')), '{"title": "Guess"}');
  assert r = unknown, 'tokens are exact';

  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'),
    '{"title": "  Spring flyer  ", "notes": "From the site", "due_on": "2026-11-02"}');
  assert (r ->> 'ok')::boolean and (r ->> 'status')::integer = 201, format('a valid call creates a task, got %s', r);
  insert into ib_ids values ('task1', (r ->> 'task_id')::uuid);

  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), jsonb_build_object(
    'title', 'Mapped', 'assignee_email', 'IB-Viewer@example.com', 'tags', jsonb_build_array('ib web', 'IB Old', 'Nope'),
    'fields', jsonb_build_object('priority', 'High', 'Budget', 5, 'Launch', '2026-12-01', 'Reviewers', jsonb_build_array('ib-editor@example.com', 'ib-outsider@example.com'), 'Mystery', 1),
    'surprise', true
  )::text);
  assert (r ->> 'status')::integer = 201, format('mapped call, got %s', r);
  insert into ib_ids values ('task2', (r ->> 'task_id')::uuid);
  assert r -> 'warnings' @> '["Ignored unknown key “surprise”"]'::jsonb, format('unknown keys warn, got %s', r -> 'warnings');
  assert r -> 'warnings' @> '["Unknown or archived tag “IB Old” skipped", "Unknown or archived tag “Nope” skipped"]'::jsonb,
    'unknown and archived tags warn';
  assert r -> 'warnings' @> '["Unknown field “Mystery” skipped"]'::jsonb, 'unknown fields warn';
  assert r::text not like '%alhc_in_%', 'the response never carries the token';

  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), jsonb_build_object(
    'title', 'Bad assignee', 'assignee_email', 'ib-outsider@example.com', 'fields', jsonb_build_object('Budget', 'lots')
  )::text);
  assert (r ->> 'status')::integer = 201, 'unmatched references still create the task';
  insert into ib_ids values ('task3', (r ->> 'task_id')::uuid);
  assert r -> 'warnings' @> '["assignee_email isn''t a member of this project; used the default assignee"]'::jsonb,
    format('a non-member assignee warns, got %s', r -> 'warnings');
  assert r::text not like '%lots%', 'warnings never echo values';

  -- Invalid bodies create nothing.
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"notes": "no title"}');
  assert (r ->> 'status')::integer = 422 and r ->> 'error' = 'title is required (a string)', format('title required, got %s', r);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "x", "due_on": "2026-02-30"}');
  assert (r ->> 'status')::integer = 422, format('impossible dates fail, got %s', r);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "x", "tags": "IB Web"}');
  assert (r ->> 'status')::integer = 422, 'tags must be an array';
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "x", "tags": null, "fields": null, "notes": null}');
  assert (r ->> 'status')::integer = 201, format('explicit nulls are fine, got %s', r);
  insert into ib_ids values ('task_nulls', (r ->> 'task_id')::uuid);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), 'not json');
  assert (r ->> 'status')::integer = 400, 'non-JSON → 400';
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '["title"]');
  assert (r ->> 'status')::integer = 400, 'arrays → 400';
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), jsonb_build_object('title', 'big', 'notes', repeat('x', 70000))::text);
  assert (r ->> 'status')::integer = 413, format('bodies over 64 KB → 413, got %s', r);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "x"}', null, null, 'bad key with spaces');
  assert (r ->> 'status')::integer = 400, 'odd idempotency keys → 400';

  -- Idempotency-Key: one task.
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "Once"}', null, null, 'order-42');
  assert (r ->> 'status')::integer = 201, 'first keyed call creates';
  insert into ib_ids values ('task_once', (r ->> 'task_id')::uuid);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "Once again"}', null, null, 'order-42');
  assert (r ->> 'status')::integer = 200 and (r ->> 'duplicate')::boolean
    and (r ->> 'task_id')::uuid = (select id from ib_ids where name = 'task_once'), format('replayed key → same task, got %s', r);
end $$;

reset role;

do $$
declare
  t1 uuid := (select id from ib_ids where name = 'task1');
  t2 uuid := (select id from ib_ids where name = 'task2');
  t3 uuid := (select id from ib_ids where name = 'task3');
  p uuid := (select id from ib_ids where name = 'p');
  admin uuid := (select id from ib_ids where name = 'admin');
  editor uuid := (select id from ib_ids where name = 'editor');
  viewer uuid := (select id from ib_ids where name = 'viewer');
begin
  assert (select title from public.tasks where id = t1) = 'Spring flyer', 'title is trimmed';
  assert (select notes from public.tasks where id = t1) = 'From the site', 'notes are kept as sent';
  assert (select due_on from public.tasks where id = t1) = '2026-11-02', 'due date set';
  assert (select source from public.tasks where id = t1) = 'inbound', 'source is inbound';
  assert (select created_by from public.tasks where id = t1) = admin, 'written as the endpoint creator';
  assert (select home_project_id from public.tasks where id = t1) = p, 'in the endpoint project';
  assert (select section_id from public.task_projects where task_id = t1 and project_id = p) = (select id from ib_ids where name = 'inbox'),
    'lands in the endpoint section';
  assert (select assignee_id from public.tasks where id = t1) = editor, 'default assignee';
  assert exists (select 1 from public.task_tags where task_id = t1 and tag_id = (select id from ib_ids where name = 'urgent') and deleted_at is null),
    'default tags';
  assert (select actor_id from public.task_stories where task_id = t1 and kind = 'created') = admin, 'the created story names the creator';
  assert (select data ->> 'endpoint_name' from public.task_stories where task_id = t1 and kind = 'inbound_received') = 'Website intake',
    'an inbound_received story';
  assert exists (select 1 from public.inbox_items where task_id = t1 and recipient_id = editor and kind = 'assigned'),
    'the assignee is notified';
  assert not exists (select 1 from public.task_followers where task_id = t1 and profile_id = admin and deleted_at is null),
    'the creator doesn''t follow every inbound task';
  assert exists (select 1 from public.task_followers where task_id = t1 and profile_id = editor and deleted_at is null),
    'the assignee follows';

  assert (select assignee_id from public.tasks where id = t2) = viewer, 'assignee_email matches a member (case-insensitive)';
  assert (select count(*) from public.task_tags where task_id = t2 and deleted_at is null) = 2, 'default + payload tags';
  assert (select value from public.task_field_values tv join public.custom_fields cf on cf.id = tv.field_id
          where tv.task_id = t2 and cf.name = 'Priority') = '"hi"'::jsonb, 'single-select by option name';
  assert (select value from public.task_field_values tv join public.custom_fields cf on cf.id = tv.field_id
          where tv.task_id = t2 and cf.name = 'Budget') = '5'::jsonb, 'number';
  assert (select value from public.task_field_values tv join public.custom_fields cf on cf.id = tv.field_id
          where tv.task_id = t2 and cf.name = 'Launch') = '"2026-12-01"'::jsonb, 'date';
  assert (select value from public.task_field_values tv join public.custom_fields cf on cf.id = tv.field_id
          where tv.task_id = t2 and cf.name = 'Reviewers') = jsonb_build_array(editor), 'people by member email only';
  assert (select assignee_id from public.tasks where id = t3) = editor, 'a non-member email falls back to the default';

  assert (select count(*) from public.tasks where home_project_id = p and source = 'inbound') = 5,
    'invalid calls and the duplicate created nothing';
  assert (select count(*) from public.tasks where title = 'Once again') = 0, 'the duplicate body was not used';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e1') and status = 'created') = 5,
    'five created calls logged';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e1') and status = 'duplicate') = 1,
    'one duplicate logged';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e1') and status = 'invalid') = 7,
    'invalid calls logged';
  assert (select current_setting('request.jwt.claim.sub', true)) = '', 'the impersonation setting is restored';
end $$;

-- Disabled, rotated, and deleted tokens create nothing ---------------------------------------------

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset
update public.inbound_endpoints set enabled = false where id = (select id from ib_ids where name = 'e1');

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "While disabled"}');
begin
  assert r = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, format('disabled → generic 401, got %s', r);
end $$;

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset
update public.inbound_endpoints set enabled = true where id = (select id from ib_ids where name = 'e1');
do $$
declare
  rotated jsonb := public.rotate_inbound_token((select id from ib_ids where name = 'e1'));
begin
  assert rotated ->> 'token' ~ '^alhc_in_[0-9a-f]{64}$' and rotated ->> 'token' <> (select val from ib_vals where name = 't1'),
    format('rotation returns a new token, got %s', rotated);
  insert into ib_vals values ('t1_new', rotated ->> 'token');
end $$;
update public.inbound_endpoints set deleted_at = now() where id = (select id from ib_ids where name = 'e4');
do $$
begin
  begin
    update public.inbound_endpoints set deleted_at = null where id = (select id from ib_ids where name = 'e4');
    raise exception 'deleted endpoints stay deleted';
  exception when check_violation then null;
  end;
end $$;

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb;
begin
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1'), '{"title": "Old token"}');
  assert r = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, 'a rotated-out token → generic 401';
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't4'), '{"title": "Deleted"}');
  assert r = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, 'a deleted endpoint → generic 401';
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1_new'), '{"title": "New token"}');
  assert (r ->> 'status')::integer = 201, format('the new token works, got %s', r);
end $$;

reset role;
do $$
begin
  assert (select count(*) from public.tasks where title in ('While disabled', 'Old token', 'Deleted')) = 0,
    'disabled, rotated, and deleted tokens created nothing';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e4')) = 0,
    'calls to a deleted endpoint aren''t logged';
end $$;

-- Signatures: missing, bad, stale, replayed --------------------------------------------------------

do $$
declare
  secret text := (select val from ib_vals where name = 's2');
  ts text := extract(epoch from clock_timestamp())::bigint::text;
  stale text := (extract(epoch from clock_timestamp())::bigint - 1000)::text;
  body text := '{"title": "Signed request", "notes": "naïve café"}';
begin
  insert into ib_vals values
    ('ts', ts),
    ('body', body),
    ('sig', 'sha256=' || encode(public.inbound_hmac_sha256(convert_to(secret, 'UTF8'), convert_to(ts || '.' || body, 'UTF8')), 'hex')),
    ('stale_ts', stale),
    ('stale_sig', 'sha256=' || encode(public.inbound_hmac_sha256(convert_to(secret, 'UTF8'), convert_to(stale || '.' || body, 'UTF8')), 'hex')),
    ('wrong_sig', 'sha256=' || encode(public.inbound_hmac_sha256(convert_to('whsec_some_other_secret_0000', 'UTF8'), convert_to(ts || '.' || body, 'UTF8')), 'hex')),
    ('keyed_sig', 'sha256=' || encode(public.inbound_hmac_sha256(convert_to(secret, 'UTF8'), convert_to(ts || '.' || '{"title": "Keyed signed"}', 'UTF8')), 'hex'));
end $$;

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  t text := (select val from ib_vals where name = 't2');
  body text := (select val from ib_vals where name = 'body');
  ts text := (select val from ib_vals where name = 'ts');
  unauthorized constant jsonb := '{"ok": false, "error": "Unauthorized", "status": 401}';
  r jsonb;
begin
  r := public.receive_inbound_webhook(t, body);
  assert r = unauthorized, format('no signature → generic 401, got %s', r);
  r := public.receive_inbound_webhook(t, body, ts, (select val from ib_vals where name = 'wrong_sig'));
  assert r = unauthorized, 'a wrong key → generic 401';
  r := public.receive_inbound_webhook(t, body || ' ', ts, (select val from ib_vals where name = 'sig'));
  assert r = unauthorized, 'a changed body → generic 401';
  r := public.receive_inbound_webhook(t, body, (select val from ib_vals where name = 'stale_ts'), (select val from ib_vals where name = 'stale_sig'));
  assert r = unauthorized, 'a stale (but correctly signed) timestamp → generic 401';
  r := public.receive_inbound_webhook(t, body, 'yesterday', (select val from ib_vals where name = 'sig'));
  assert r = unauthorized, 'a malformed timestamp → generic 401';

  r := public.receive_inbound_webhook(t, body, ts, upper((select val from ib_vals where name = 'sig')));
  assert (r ->> 'status')::integer = 201, format('a correct signature creates the task (hex case-insensitive), got %s', r);
  r := public.receive_inbound_webhook(t, body, ts, (select val from ib_vals where name = 'sig'));
  assert r = unauthorized, format('a replay → generic 401, got %s', r);

  r := public.receive_inbound_webhook(t, '{"title": "Keyed signed"}', ts, (select val from ib_vals where name = 'keyed_sig'), 'k-1');
  assert (r ->> 'status')::integer = 201, 'keyed signed call';
  r := public.receive_inbound_webhook(t, '{"title": "Keyed signed"}', ts, (select val from ib_vals where name = 'keyed_sig'), 'k-1');
  assert (r ->> 'status')::integer = 200 and (r ->> 'duplicate')::boolean, 'a keyed replay returns the original task';
end $$;

reset role;
do $$
declare
  e2 uuid := (select id from ib_ids where name = 'e2');
begin
  assert (select count(*) from public.tasks where title = 'Signed request') = 1, 'one task despite the replay';
  assert (select notes from public.tasks where title = 'Signed request') = 'naïve café', 'UTF-8 bodies verify and survive';
  assert (select count(*) from public.tasks where title = 'Keyed signed') = 1, 'one keyed signed task';
  assert (select count(*) from public.inbound_calls where endpoint_id = e2 and status = 'rejected') = 6,
    format('six rejections logged, got %s', (select count(*) from public.inbound_calls where endpoint_id = e2 and status = 'rejected'));
  assert exists (select 1 from public.inbound_calls where endpoint_id = e2 and error like 'Stale X-ALHC-Timestamp%'), 'stale reason logged';
  assert exists (select 1 from public.inbound_calls where endpoint_id = e2 and error like 'Replayed request%'), 'replay reason logged';
  assert not exists (
    select 1 from public.inbound_calls
    where coalesce(error, '') ~ '(alhc_in_|whsec_|sha256=)' or warnings::text ~ '(alhc_in_|whsec_|sha256=)'
  ), 'the log never holds tokens, secrets, or signatures';
  assert not exists (
    select 1 from information_schema.columns where table_schema = 'public' and column_name ilike '%signature%'
  ), 'signatures are never stored';
  assert not exists (select 1 from public.inbound_endpoints where token_hash like 'alhc_in_%' or token_hint like 'alhc_in_%'),
    'tokens are stored only as hashes';
end $$;

-- Removing the signing secret, and asking for one later ---------------------------------------------

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset
do $$
declare
  r jsonb;
begin
  r := public.set_inbound_signing_secret((select id from ib_ids where name = 'e2'), false);
  assert r ->> 'signing_secret' is null, 'removing returns nothing';
  assert (select signing_secret_set_at from public.inbound_endpoints where id = (select id from ib_ids where name = 'e2')) is null,
    'no signing secret now';
  r := public.set_inbound_signing_secret((select id from ib_ids where name = 'e2'), true);
  assert r ->> 'signing_secret' ~ '^whsec_[0-9a-f]{64}$' and r ->> 'signing_secret' <> (select val from ib_vals where name = 's2'),
    'a new secret is returned once';
end $$;

reset role;
do $$
begin
  assert (select signing_secret from public.inbound_endpoints where id = (select id from ib_ids where name = 'e2'))
    <> (select val from ib_vals where name = 's2'), 'the old secret is retired';
end $$;

-- Rate limit ----------------------------------------------------------------------------------------

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  t text := (select val from ib_vals where name = 't3');
  r jsonb;
begin
  for i in 1 .. 60 loop
    r := public.receive_inbound_webhook(t, '{"notes": "no title"}');
    assert (r ->> 'status')::integer = 422, format('call %s is processed, got %s', i, r);
  end loop;
  r := public.receive_inbound_webhook(t, '{"title": "One too many"}');
  assert (r ->> 'status')::integer = 429, format('the 61st call in a minute → 429, got %s', r);
  r := public.receive_inbound_webhook(t, '{"title": "Still too many"}');
  assert (r ->> 'status')::integer = 429, 'still limited';
end $$;

reset role;
do $$
begin
  assert (select count(*) from public.tasks where title in ('One too many', 'Still too many')) = 0, 'rate-limited calls create nothing';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e3') and status = 'rate_limited') = 1,
    'one rate-limited row per minute';
end $$;

-- The creator's access is re-checked: an archived project (everyone capped at Viewer) creates nothing

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000001', false) is not null as ok \gset
do $$ begin perform public.set_project_archived((select id from ib_ids where name = 'p'), true); end $$;

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb := public.receive_inbound_webhook((select val from ib_vals where name = 't1_new'), '{"title": "While archived"}');
begin
  assert r = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, format('archived → generic 401, got %s', r);
end $$;

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000001', false) is not null as ok \gset
do $$
begin
  perform public.set_project_archived((select id from ib_ids where name = 'p'), false);
  perform public.update_project_member_role((select id from ib_ids where name = 'p'), (select id from ib_ids where name = 'admin'), 'commenter');
end $$;

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb := public.receive_inbound_webhook((select val from ib_vals where name = 't1_new'), '{"title": "Creator demoted"}');
begin
  assert r = '{"ok": false, "error": "Unauthorized", "status": 401}'::jsonb, format('a creator below Editor → generic 401, got %s', r);
end $$;

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000001', false) is not null as ok \gset
do $$ begin perform public.update_project_member_role((select id from ib_ids where name = 'p'), (select id from ib_ids where name = 'admin'), 'admin'); end $$;

reset role;
do $$
begin
  assert (select count(*) from public.tasks where title in ('While archived', 'Creator demoted')) = 0, 'nothing created without the creator''s access';
  assert (select count(*) from public.inbound_calls where endpoint_id = (select id from ib_ids where name = 'e1')
          and error like 'The endpoint''s creator can no longer add tasks%') = 2, 'both refusals are logged for the admin';
