-- Rules: inbound_received { endpoint_id? } and source_is inbound ------------------------------------

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset
do $$
declare
  p uuid := (select id from ib_ids where name = 'p');
  other_endpoint uuid;
begin
  insert into public.rules (project_id, name, enabled, trigger_type, trigger_config, actions) values
    (p, 'Website only', true, 'inbound_received', jsonb_build_object('endpoint_id', (select id from ib_ids where name = 'e1')),
     '[{"type": "add_comment", "body": "Thanks from the website rule"}]'),
    (p, 'Any inbound', true, 'inbound_received', '{}', jsonb_build_array(jsonb_build_object('type', 'move_section', 'section_id', (select id from ib_ids where name = 'doing')))),
    (p, 'Inbound source', true, 'task_created', '{}', '[{"type": "add_comment", "body": "Came in from outside"}]');
  update public.rules set conditions = '[{"type": "source_is", "source": "inbound"}]' where name = 'Inbound source' and project_id = p;
  begin
    insert into public.rules (project_id, name, trigger_type, trigger_config, actions) values
      (p, 'Wrong endpoint', 'inbound_received', jsonb_build_object('endpoint_id', gen_random_uuid()), '[{"type": "add_comment", "body": "x"}]');
    raise exception 'an endpoint outside the project should fail';
  exception when check_violation then null;
  end;
  begin
    insert into public.rules (project_id, name, trigger_type, conditions, actions) values
      (p, 'Bad source', 'task_created', '[{"type": "source_is", "source": "smoke-signal"}]', '[{"type": "add_comment", "body": "x"}]');
    raise exception 'unknown sources should fail';
  exception when check_violation then null;
  end;
end $$;

set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb;
begin
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't1_new'), '{"title": "Rule check website"}');
  assert (r ->> 'status')::integer = 201, format('rule check, got %s', r);
  insert into ib_ids values ('rule_task1', (r ->> 'task_id')::uuid);
  r := public.receive_inbound_webhook((select val from ib_vals where name = 't2'), '{"title": "Rule check other"}');
  assert (r ->> 'status')::integer = 401, 'the signed endpoint still wants a signature';
end $$;

reset role;
do $$
declare
  t1 uuid := (select id from ib_ids where name = 'rule_task1');
  p uuid := (select id from ib_ids where name = 'p');
begin
  assert exists (select 1 from public.comments where task_id = t1 and body = 'Thanks from the website rule'), 'the endpoint rule fired';
  assert (select section_id from public.task_projects where task_id = t1 and project_id = p) = (select id from ib_ids where name = 'doing'),
    'the any-endpoint rule fired';
end $$;
-- task_created rules fire at commit (deferred), so check them in a later statement.
do $$
declare
  t1 uuid := (select id from ib_ids where name = 'rule_task1');
begin
  assert exists (select 1 from public.comments where task_id = t1 and body = 'Came in from outside'), 'source_is inbound matches';
  assert not exists (select 1 from public.comments where task_id = (select id from ib_ids where name = 'task1') and body = 'Came in from outside'),
    'rules don''t run for earlier tasks';
end $$;

-- The endpoint filter: a task created through another endpoint doesn't fire the website-only rule.
do $$
declare
  secret text := (select signing_secret from public.inbound_endpoints where id = (select id from ib_ids where name = 'e2'));
  ts text := extract(epoch from clock_timestamp())::bigint::text;
  body text := '{"title": "Rule check signed"}';
begin
  insert into ib_vals values ('rule_ts', ts),
    ('rule_sig', 'sha256=' || encode(public.inbound_hmac_sha256(convert_to(secret, 'UTF8'), convert_to(ts || '.' || body, 'UTF8')), 'hex'));
end $$;
set role anon;
select set_config('request.jwt.claim.sub', '', false) is not null as ok \gset
do $$
declare
  r jsonb := public.receive_inbound_webhook((select val from ib_vals where name = 't2'), '{"title": "Rule check signed"}',
    (select val from ib_vals where name = 'rule_ts'), (select val from ib_vals where name = 'rule_sig'));
begin
  assert (r ->> 'status')::integer = 201, format('signed rule check, got %s', r);
  insert into ib_ids values ('rule_task2', (r ->> 'task_id')::uuid);
end $$;
reset role;
do $$
declare
  t2 uuid := (select id from ib_ids where name = 'rule_task2');
begin
  assert not exists (select 1 from public.comments where task_id = t2 and body = 'Thanks from the website rule'), 'the endpoint filter holds';
  assert (select section_id from public.task_projects where task_id = t2 and project_id = (select id from ib_ids where name = 'p'))
    = (select id from ib_ids where name = 'doing'), 'the any-endpoint rule fires for every endpoint';
end $$;

-- Imports and copies still never fire rules -----------------------------------------------------------

do $$
declare
  def text := pg_get_functiondef('public.fire_rules(text, uuid, uuid, jsonb)'::regprocedure);
  runs integer := (select count(*) from public.rule_runs);
begin
  assert def like '%if public.import_context_id() is not null then%' and def like '%if public.copy_context_id() is not null then%',
    'fire_rules keeps its import and copy checks';
  perform set_config('alhc.import_run_id', gen_random_uuid()::text, true);
  perform public.fire_rules('inbound_received', (select id from ib_ids where name = 'task1'), (select id from ib_ids where name = 'p'),
    jsonb_build_object('endpoint_id', (select id from ib_ids where name = 'e1')));
  assert (select count(*) from public.rule_runs) = runs, 'nothing fires during an import';
  perform set_config('alhc.import_run_id', '', true);
  perform set_config('alhc.copy_id', gen_random_uuid()::text, true);
  perform public.fire_rules('inbound_received', (select id from ib_ids where name = 'task1'), (select id from ib_ids where name = 'p'),
    jsonb_build_object('endpoint_id', (select id from ib_ids where name = 'e1')));
  assert (select count(*) from public.rule_runs) = runs, 'nothing fires during a copy';
  perform set_config('alhc.copy_id', '', true);
  assert pg_get_functiondef('public.notify_with(uuid, uuid, text, uuid, jsonb)'::regprocedure) like '%import_context_id()%copy_context_id()%',
    'notify_with keeps its checks';
  assert pg_get_functiondef('public.add_story(uuid, text, jsonb)'::regprocedure) like '%import_context_id()%',
    'add_story keeps its checks';
end $$;

-- Copies never carry endpoints ------------------------------------------------------------------------

do $$
declare
  snap jsonb := public.project_snapshot((select id from ib_ids where name = 'p'), '{"rules": true}'::jsonb);
begin
  assert snap::text not like '%alhc_in_%' and snap::text not like '%whsec_%' and snap::text not like '%token_hash%',
    'snapshots carry no endpoint tokens or secrets';
end $$;

-- The log: Admin+ read it, nobody writes it -----------------------------------------------------------

set role authenticated;
select set_config('request.jwt.claim.sub', 'f6f6f6f6-0000-4000-8000-000000000002', false) is not null as ok \gset
do $$
begin
  assert (select count(*) from public.inbound_calls) > 0, 'admins read the log';
  begin
    perform replay_digest from public.inbound_calls limit 1;
    raise exception 'replay digests are internal';
  exception when insufficient_privilege then null;
  end;
  begin
    insert into public.inbound_calls (endpoint_id, project_id, status, http_status)
    values ((select id from ib_ids where name = 'e1'), (select id from ib_ids where name = 'p'), 'created', 201);
    raise exception 'nobody writes the log';
  exception when insufficient_privilege then null;
  end;
  begin
    perform public.log_inbound_call(null::public.inbound_endpoints, 'created', 201);
    raise exception 'the log helper is internal';
  exception when insufficient_privilege then null;
  end;
end $$;

-- EXECUTE surface: anon gets exactly the public form RPCs and the receiver ---------------------------

reset role;
do $$
declare
  exposed text;
begin
  select string_agg(p.proname, ',' order by p.proname) into exposed
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prosecdef and has_function_privilege('anon', p.oid, 'execute');
  assert exposed = 'get_public_form,receive_inbound_webhook,submit_form', format('anon SECURITY DEFINER surface: %s', exposed);

  assert not has_function_privilege('anon', 'public.create_inbound_endpoint(uuid, text, uuid, uuid, uuid[], boolean)', 'execute')
    and not has_function_privilege('anon', 'public.rotate_inbound_token(uuid)', 'execute')
    and not has_function_privilege('anon', 'public.set_inbound_signing_secret(uuid, boolean)', 'execute'),
    'anon manages nothing';
  assert not has_function_privilege('authenticated', 'public.inbound_hmac_sha256(bytea, bytea)', 'execute')
    and not has_function_privilege('anon', 'public.inbound_hmac_sha256(bytea, bytea)', 'execute'), 'HMAC is internal';
  assert not has_function_privilege('authenticated', 'public.log_inbound_call(public.inbound_endpoints, text, integer, text, uuid, jsonb, text, text)', 'execute'),
    'the log helper is internal';
  assert not has_table_privilege('anon', 'public.inbound_endpoints', 'select')
    and not has_table_privilege('anon', 'public.inbound_endpoints', 'insert')
    and not has_table_privilege('anon', 'public.inbound_calls', 'select'), 'anon has no table grants';
  assert not has_column_privilege('authenticated', 'public.inbound_endpoints', 'token_hash', 'select')
    and not has_column_privilege('authenticated', 'public.inbound_endpoints', 'signing_secret', 'select')
    and not has_column_privilege('authenticated', 'public.inbound_endpoints', 'token_hash', 'update')
    and not has_column_privilege('authenticated', 'public.inbound_endpoints', 'signing_secret', 'insert'),
    'no client reads or writes hashes and secrets';
  assert not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prosecdef and p.proname in (
      'create_inbound_endpoint', 'rotate_inbound_token', 'set_inbound_signing_secret', 'guard_inbound_endpoint', 'log_inbound_call'
    )
  ), 'endpoint management is SECURITY INVOKER';
  -- Since Email live the helper stays (AGENTS.md → Conventions); it must stay internal.
  assert not exists (
    select 1 from pg_proc where proname = 'alhc_patch_function'
      and (has_function_privilege('authenticated', oid, 'execute') or has_function_privilege('anon', oid, 'execute'))
  ), 'the patch helper is internal';
end $$;

select 'inbound integrations smoke: all assertions passed' as result;
